        except OSError as error:
            raise RuntimeError('cannot observe process ownership for admission') from error
        if uid != os.getuid():
            continue
        try:
            raw = (item / 'stat').read_text()
            fields = raw[raw.rfind(')') + 2:].split()
            if fields[0] in {'Z', 'X'}:
